def is_palindrome(s: str) -> bool:
    """Return True if s reads the same forwards and backwards, ignoring case and non-alphanumeric characters."""
    filtered = ''.join(ch.lower() for ch in s if ch.isalnum())
    return filtered == filtered[::-1]

def merge_intervals(iv: list) -> list:
    """Merge overlapping or touching [start, end] intervals; return them sorted by start."""
    if not iv:
        return []
    # sort by start
    intervals = sorted(iv, key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals[1:]:
        last = merged[-1]
        # if current starts before or at the end of last, merge
        if current[0] <= last[1]:
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)
    return merged

