def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case. Consecutive capitals stay together (HTTPServer -> http_server)."""
    if not s:
        return ''
    result = []
    i = 0
    while i < len(s):
        if s[i].isupper():
            j = i+1
            while j < len(s) and s[j].isupper():
                j += 1
            # if next is lower, separate last capital
            if j < len(s) and s[j].islower() and j - i > 1:
                part = s[i:j-1].lower()
                result.append(part)
                result.append('_')
                i = j-1
            else:
                part = s[i:j].lower()
                result.append(part)
                i = j
        else:
            result.append(s[i])
            i += 1
    snake = ''.join(result).replace('__', '_')
    if snake.startswith('_'):
        snake = snake[1:]
    if snake.endswith('_'):
        snake = snake[:-1]
    return snake

